// Convertir audio binario a base64 y transcribir con Google STT
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const base64Audio = buffer.toString('base64');

const sttResponse = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://speech.googleapis.com/v1/speech:recognize?key=AIzaSyD2bX9W2QthYERE1VNX0HRUJsa9iNwQ_kk',
  body: {
    config: {
      encoding: 'OGG_OPUS',
      sampleRateHertz: 16000,
      languageCode: 'es-419',
      enableAutomaticPunctuation: true,
      model: 'latest_long'
    },
    audio: {
      content: base64Audio
    }
  },
  json: true,
  headers: { 'Content-Type': 'application/json' }
});

const transcript = (sttResponse.results || [])
  .map(r => r.alternatives?.[0]?.transcript)
  .filter(Boolean)
  .join(' ');

if (!transcript) {
  throw new Error('No se pudo transcribir el audio. Intenta enviando un mensaje de texto.');
}

return [{ json: { text: transcript } }];

const text = $input.first().json.text;
const trigger = $('Trigger').first().json;

// Fecha/hora actual en zona horaria de Venezuela
const now = new Date();
const formatter = new Intl.DateTimeFormat('es-VE', {
  timeZone: 'America/Caracas',
  year: 'numeric', month: '2-digit', day: '2-digit',
  hour: '2-digit', minute: '2-digit', hour12: false
});
const caracasTime = formatter.format(now);

// Obtener fecha ISO en Caracas para cálculos relativos
const caracasISO = now.toLocaleString('sv-SE', { timeZone: 'America/Caracas' });

const systemPrompt = `Eres un asistente de recordatorios por WhatsApp. Extraes información estructurada de mensajes donde una persona pide recordarle algo a otra persona.

Fecha y hora actual: ${caracasTime}
Fecha ISO actual: ${caracasISO}
Zona horaria: America/Caracas (UTC-4)

Extrae del mensaje:
1. targetPhone: Número de teléfono destino con código de país, sin '+' ni espacios (ej: 584121234567). Si dan número local venezolano (0412...), reemplaza el 0 inicial por 58. Si dan solo el número sin código, asume 58 (Venezuela).
2. date: Fecha del recordatorio en formato YYYY-MM-DD. Interpreta expresiones relativas como "mañana", "el lunes", "en 3 días", "pasado mañana", etc. relativo a la fecha actual.
3. time: Hora del recordatorio en formato HH:mm (24h). Si no especifican hora, usa "09:00".
4. message: El asunto/mensaje del recordatorio, redactado claro y conciso para quien lo va a recibir.
5. targetName: Nombre del destinatario si se menciona, sino null.
6. understood: true si pudiste extraer al menos targetPhone y message, false si falta información crítica.

SOLO responde con JSON válido:
{"targetPhone":"...","date":"YYYY-MM-DD","time":"HH:mm","message":"...","targetName":null,"understood":true}`;

// Llamar a Gemini API
const geminiResponse = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://generativelanguage.googleapis.com/v1beta/models/gemini-2.0-flash:generateContent?key=AIzaSyD2bX9W2QthYERE1VNX0HRUJsa9iNwQ_kk',
  body: {
    system_instruction: { parts: [{ text: systemPrompt }] },
    contents: [{ parts: [{ text: text }] }],
    generationConfig: {
      temperature: 0.1,
      responseMimeType: 'application/json'
    }
  },
  json: true,
  headers: { 'Content-Type': 'application/json' }
});

const aiText = geminiResponse.candidates?.[0]?.content?.parts?.[0]?.text || '';

let parsed;
try {
  parsed = JSON.parse(aiText);
} catch (e) {
  return [{
    json: {
      understood: false,
      error: 'No se pudo interpretar la respuesta de IA: ' + aiText.substring(0, 200),
      senderPhone: trigger.senderPhone,
      phoneNumberId: trigger.phoneNumberId,
      wabaToken: trigger.wabaToken
    }
  }];
}

if (!parsed.understood || !parsed.targetPhone || !parsed.message) {
  return [{
    json: {
      understood: false,
      error: !parsed.targetPhone
        ? 'No encontré un número de teléfono destino en tu mensaje.'
        : 'No pude entender completamente el recordatorio.',
      senderPhone: trigger.senderPhone,
      phoneNumberId: trigger.phoneNumberId,
      wabaToken: trigger.wabaToken
    }
  }];
}

// Construir datetime ISO para el Wait node (UTC-4 Venezuela)
const reminderDateTime = `${parsed.date}T${parsed.time}:00-04:00`;

// Formatear mensajes
const targetDisplay = parsed.targetName
  ? `${parsed.targetName} (${parsed.targetPhone})`
  : parsed.targetPhone;

const senderDisplay = trigger.senderName || trigger.senderPhone;

const confirmMessage = `✅ *Recordatorio agendado*\n\n📅 Fecha: ${parsed.date}\n⏰ Hora: ${parsed.time}\n📱 Para: ${targetDisplay}\n💬 _"${parsed.message}"_\n\nTe avisaré cuando lo envíe.`;

const reminderMessage = `👋 Hola${parsed.targetName ? ' ' + parsed.targetName : ''}!\n\n${senderDisplay} te envía este recordatorio:\n\n💬 *${parsed.message}*`;

const notifyMessage = `✅ Listo, le envié el recordatorio a ${targetDisplay}.`;

return [{
  json: {
    understood: true,
    targetPhone: parsed.targetPhone,
    date: parsed.date,
    time: parsed.time,
    message: parsed.message,
    targetName: parsed.targetName,
    reminderDateTime,
    confirmMessage,
    reminderMessage,
    notifyMessage,
    senderPhone: trigger.senderPhone,
    senderName: trigger.senderName,
    phoneNumberId: trigger.phoneNumberId,
    wabaToken: trigger.wabaToken
  }
}];

const data = $input.first().json;

// Enviar confirmación a Persona1 vía WABA
await this.helpers.httpRequest({
  method: 'POST',
  url: `https://graph.facebook.com/v21.0/${data.phoneNumberId}/messages`,
  body: {
    messaging_product: 'whatsapp',
    to: data.senderPhone,
    type: 'text',
    text: { body: data.confirmMessage }
  },
  json: true,
  headers: {
    'Authorization': `Bearer ${data.wabaToken}`,
    'Content-Type': 'application/json'
  }
});

// Pasar TODOS los datos para nodos siguientes (Wait necesita el contexto)
return [{ json: data }];

const data = $input.first().json;

const errorMsg = `❌ No pude crear el recordatorio.\n\n${data.error || 'No logré extraer la información necesaria.'}\n\nPor favor intenta de nuevo incluyendo:\n📱 Número de teléfono\n📅 Fecha y hora\n💬 Mensaje del recordatorio\n\nEjemplo: \"Recuérdale al 0412-1234567 mañana a las 3pm que tiene cita con el doctor\"`;

await this.helpers.httpRequest({
  method: 'POST',
  url: `https://graph.facebook.com/v21.0/${data.phoneNumberId}/messages`,
  body: {
    messaging_product: 'whatsapp',
    to: data.senderPhone,
    type: 'text',
    text: { body: errorMsg }
  },
  json: true,
  headers: {
    'Authorization': `Bearer ${data.wabaToken}`,
    'Content-Type': 'application/json'
  }
});

return [{ json: { success: false, error: data.error } }];

const data = $input.first().json;

// Enviar recordatorio a Persona2 vía WABA
await this.helpers.httpRequest({
  method: 'POST',
  url: `https://graph.facebook.com/v21.0/${data.phoneNumberId}/messages`,
  body: {
    messaging_product: 'whatsapp',
    to: data.targetPhone,
    type: 'text',
    text: { body: data.reminderMessage }
  },
  json: true,
  headers: {
    'Authorization': `Bearer ${data.wabaToken}`,
    'Content-Type': 'application/json'
  }
});

return [{ json: data }];

const data = $input.first().json;

// Notificar a Persona1 que el recordatorio fue enviado
await this.helpers.httpRequest({
  method: 'POST',
  url: `https://graph.facebook.com/v21.0/${data.phoneNumberId}/messages`,
  body: {
    messaging_product: 'whatsapp',
    to: data.senderPhone,
    type: 'text',
    text: { body: data.notifyMessage }
  },
  json: true,
  headers: {
    'Authorization': `Bearer ${data.wabaToken}`,
    'Content-Type': 'application/json'
  }
});

return [{
  json: {
    success: true,
    targetPhone: data.targetPhone,
    date: data.date,
    time: data.time,
    message: data.message
  }
}];
